sql.where:
ev.deleted = 0

  AND ev.status = #{status}


  AND ev.company_id = #{companyId}


  AND ev.period_year = #{periodYear}


  AND ev.period_half = #{periodHalf}


  AND ev.evaluation_type = #{evaluationType}


  AND (
       ev.evaluation_no LIKE '%' + #{keyword} + '%'
    OR c.name LIKE '%' + #{keyword} + '%'
    OR c.business_number LIKE '%' + #{keyword} + '%'
  )

mapper.update:
UPDATE tb_evaluation
   SET deleted = 1, updated_at = SYSUTCDATETIME()
 WHERE id = #{id}

mapper.select:
SELECT ISNULL(MAX(CAST(RIGHT(evaluation_no, 4) AS INT)), 0)
  FROM tb_evaluation
 WHERE period_year = #{periodYear} AND period_half = #{periodHalf}

SELECT COUNT(1)
  FROM tb_evaluation
 WHERE deleted = 0
   AND company_id = #{companyId}
   AND period_year = #{periodYear}
   AND period_half = #{periodHalf}
   AND evaluation_type = #{evaluationType}
